// Meta's one-time check when the Callback URL is saved in the App Dashboard:
// echo hub.challenge back only if hub.verify_token is our secret.
const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === '{{ $env.META_STATUS_WEBHOOK_SECRET }}';
return [{ json: { ok, challenge: ok ? String(q['hub.challenge'] || '') : 'forbidden' } }];

// Meta's delivery statuses for FMS's own number, one item each, to be saved
// in whatsapp_messages. A 200 from /messages only meant "accepted"; whether
// the message reached the phone arrives here, seconds or days later.
const PHONE_ID = '{{ $env.META_PHONE_NUMBER_ID }}';
const STATUSES = ['sent', 'delivered', 'read', 'failed'];
const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();

const out = [];
for (const entry of $input.first().json.body?.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (change.field !== 'messages' || value.metadata?.phone_number_id !== PHONE_ID) continue;
    for (const s of value.statuses || []) {
      if (!s.id || !STATUSES.includes(s.status)) continue;
      const e = (s.errors || [])[0];
      const reason = e
        ? [e.title || e.message, e.error_data?.details].map(clean).filter(Boolean)
          .filter((v, i, a) => a.indexOf(v) === i).join(': ') + (e.code ? ` (${e.code})` : '')
        : '';
      out.push({ json: {
        wamid: s.id,
        status: s.status,
        at: Number(s.timestamp) || Math.floor(Date.now() / 1000),
        error: reason,
        // "<title> @ <time>" from the alerts workflow, for a status that
        // arrives before that workflow has saved the message.
        title: clean(s.biz_opaque_callback_data).replace(/ @ [^@]*$/, ''),
      } });
    }
  }
}
return out;

// Template mode only: one WhatsApp notice for alerts that newly failed (the
// rows "Save status" changed to 'failed'), sent through the alerts workflow
// so it goes out as the template too. Without a template the notice would be
// dropped for the same 24-hour reason, so it is skipped: those alerts are
// resent when the owner next messages the business number instead.
// Skipped: other parts of a report already reported in the last 30 min, and
// failures of these notices themselves, so a problem that stops every
// message (payment, paused template) can't loop.
const TEMPLATE = '{{ $env.WHATSAPP_TEMPLATE_NAME }}'.trim();
const NOTICE_TITLE = '❌ WhatsApp alert not delivered';
const SAME_REPORT_MS = 30 * 60 * 1000;
if (!TEMPLATE) return [];

const state = $getWorkflowStaticData('global');
state.recent = state.recent || {};
const now = Date.now();
for (const [k, t] of Object.entries(state.recent)) if (now - t > SAME_REPORT_MS) delete state.recent[k];

const when = (t) => new Date(t).toLocaleString('en-PK', {
  timeZone: 'Asia/Karachi', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit',
});
const cut = (s, n) => (s.length > n ? `${s.slice(0, n - 1)}…` : s);
const lines = [];
for (const r of $input.all().map((i) => i.json)) {
  if (r.status !== 'failed' || !r.wamid) continue;
  const title = String(r.title || '');
  if (title.startsWith(NOTICE_TITLE)) continue;
  const label = title.replace(/ \(\d+\/\d+\)$/, '');
  const key = label || r.wamid;
  if (state.recent[key]) continue;
  state.recent[key] = now;
  lines.push(`• ${label || 'An FMS message'} (sent ${when(r.sent_at)}): ${cut(r.error || 'no reason given', 250)}`);
}
if (lines.length === 0) return [];
const shown = lines.slice(0, 10);
if (lines.length > 10) shown.push(`…and ${lines.length - 10} more`);
return [{ json: { message: `${NOTICE_TITLE}\n${shown.join('\n')}\nOpen FMS to see what it said.` } }];

// The owner messaged the business number: Meta's 24-hour window is open
// again, so free-form text is delivered for the next 24 h. One item if so,
// whatever they wrote; the next nodes resend what was missed.
const PHONE_ID = '{{ $env.META_PHONE_NUMBER_ID }}';
const OWNER = '{{ $env.WHATSAPP_TO_NUMBER }}'.replace(/\D/g, '');

for (const entry of $input.first().json.body?.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    if (change.field !== 'messages' || value.metadata?.phone_number_id !== PHONE_ID) continue;
    if ((value.messages || []).some((m) => String(m.from || '').replace(/\D/g, '') === OWNER)) {
      return [{ json: { ownerWrote: true } }];
    }
  }
}
return [];

// Turns the missed alerts just claimed from whatsapp_messages into messages
// for the alerts workflow, oldest first, each starting with a "(Missed: …)"
// line that the alerts workflow keeps out of the title, like "(Delayed: …)".
// Nothing missed: a short "nothing missed" reply (at most every 6 h), so a
// "hi" to the business number always gets an answer.
const LIMIT = 30; // must match the claim query
const NOTICE_TITLE = '❌ WhatsApp alert not delivered';
const ACK = '✅ FMS: no missed alerts. New alerts reach this chat for the next 24 hours.';
const MORE = '(That was';
const ACK_EVERY_MS = 6 * 3600 * 1000;
const MISSED = /^\(Missed:[^\n]*\)\n/;

const when = (t) => new Date(t).toLocaleString('en-PK', {
  timeZone: 'Asia/Karachi', day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit',
});
const claimed = $input.all().map((i) => i.json).filter((r) => r.wamid && r.message);
const rows = claimed
  .filter((r) => !String(r.title || '').startsWith(NOTICE_TITLE)
    && !r.message.startsWith(ACK) && !r.message.startsWith(MORE))
  .sort((a, b) => new Date(a.sent_at) - new Date(b.sent_at));

if (rows.length === 0) {
  const state = $getWorkflowStaticData('global');
  if (Date.now() - (state.ackAt || 0) < ACK_EVERY_MS) return [];
  state.ackAt = Date.now();
  return [{ json: { message: ACK } }];
}

const out = rows.map((r) => ({
  json: { message: `(Missed: first sent ${when(r.sent_at)})\n${r.message.replace(MISSED, '')}` },
}));
if (claimed.length >= LIMIT) {
  out.push({ json: { message: `${MORE} ${LIMIT} missed alerts; send another message for the rest.)` } });
}
return out;
